mapper.select:
WITH RECURSIVE descendants AS (
    SELECT id, parent_id, 0 AS depth FROM sys_org
    WHERE id = #{orgId}
      AND tenant_id = #{tenantId}
      AND delete_flag = 0
    UNION ALL
    SELECT o.id, o.parent_id, d.depth + 1 FROM sys_org o
    INNER JOIN descendants d ON o.parent_id = d.id
    WHERE o.tenant_id = #{tenantId}
      AND o.delete_flag = 0
      AND d.depth < 100
)
SELECT id FROM descendants
